from __future__ import annotations

import pytest

from llm_router import (
    LLMRouter,
    Model,
    Provider,
    ProviderError,
    ProviderLimits,
    RouterProfile,
)
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_error_response,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")


def failure_response() -> ScriptedResponse:
    return ScriptedResponse(
        status_code=400,
        headers={"Content-Type": "application/json"},
        body=openai_error_response(status_code=400, message="cool down"),
    )


def success_response(text: str) -> ScriptedResponse:
    return ScriptedResponse(
        status_code=200,
        headers={"Content-Type": "application/json"},
        body=openai_success_response(text=text),
    )


@pytest.mark.verifies("TREQ_RATE_LIMIT_AVAILABILITY_SELECTION[revision==1]")
def test_all_auto_keys_blocked_selects_shortest_wait_without_error(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    value = "credential-value"
    for index in (1, 2, 3):
        monkeypatch.setenv(f"OPENROUTER_API_KEY_{index}", f"{value}-{index}")

    router = LLMRouter(
        RouterProfile(
            provider=Provider.OPENROUTER,
            model=Model.DEEPSEEK_V3,
            key_id="auto",
        ),
        max_attempts=1,
        wait_for_cooldown_if_all_blocked=True,
        limits_by_provider={
            Provider.OPENROUTER: ProviderLimits(
                rps=0.0,
                rpm=0.0,
                cooldown_seconds=1.5,
                cooldown_after_failures=1,
            )
        },
    )
    path = openai_chat_path()
    with (
        ScriptedHTTPServer(
            port=0,
            routes={
                ("POST", path): [
                    failure_response(),
                    success_response("two"),
                    failure_response(),
                    failure_response(),
                    success_response("final"),
                ]
            },
        ) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        with pytest.raises(ProviderError, match=r"Provider request failed"):
            router.query("fail first")
        assert router.query("use second").routing_trace[-1].key_id == 2
        with pytest.raises(ProviderError, match=r"Provider request failed"):
            router.query("fail third")
        with pytest.raises(ProviderError, match=r"Provider request failed"):
            router.query("fail second")

        response = router.query("all blocked")

    attempt = response.routing_trace[-1]
    assert attempt.key_id == 1
    assert 0.0 < attempt.wait_seconds <= 1.5
